     --reply-detached-text-color: #999999;
     --reply-detached-name-color: #999999;
     --reply-bar-bg: #2C2C2C;                   /* 夜间深灰底 */
     --reply-bar-text-color: #999999;           /* 夜间文字颜色 */

     /* === 翻译内容 === */
     --translation-text-color: #DADADA;
     --trans-detached-bg: #181818;
     --trans-detached-color: #D1D1D1;
     --trans-btn1: #5E5E5E;

     /* === 我方气泡 === */
     --bubble-me-bg: #28b561;
     --bubble-me-color: #04120a;

     /* === 对方气泡 === */
     --bubble-them-bg: #2C2C2C;
     --bubble-them-color: #DADADA;

     /* === 语音 === */
     --voice-transcription-color: #131313;
