     /* === 视频 === */
     --call-avatar-image: url('https://i.postimg.cc/VLy1q1y3/wu-biao-ti173-20260606111259.png');

     /* === 转账（夜间不压暗，保持与日间明亮一致） === */
     --transfer-card-bg: #FA9D3B;
     --transfer-card-bg-received: #FDCE9D;
