  --input-area-border-top:none;
  --input-box-bg:var(--ry-page);
  --input-box-border:none;
  --input-box-color:var(--ry-input-ink);
  --input-box-placeholder:transparent;
  --input-box-shadow:none;
  --input-caret-color:var(--ry-input-ink);
  --send-btn-bg:var(--ry-page);
  --send-btn-size:auto;
  --send-btn-shadow:none;
  --btn-send-scale:1;
  --plus-btn-bg:transparent;

  --transfer-card-bg:var(--ry-card-bg);
  --transfer-card-border:1px solid var(--ry-card-bd);
  --transfer-card-radius:8px;
  --transfer-card-shadow:none;
  --transfer-icon-bg:var(--ry-card-ic);
  --transfer-icon-color:#666666;
  --transfer-amount-color:#444444;
  --transfer-me-card-bg:var(--ry-card-bg);
  --transfer-me-card-border:1px solid var(--ry-card-bd);
  --transfer-me-icon-bg:var(--ry-card-ic);
  --transfer-me-amount-color:#444444;
  --transfer-me-label-color:var(--ry-card-ink);
  --transfer-me-subtitle-color:var(--ry-card-ink);
  --transfer-me-status-color:var(--ry-card-ink);
  --transfer-me-divider-color:var(--ry-card-bd);
