  --transfer-them-label-color:var(--ry-card-ink);
  --transfer-them-subtitle-color:var(--ry-card-ink);
  --transfer-them-status-color:var(--ry-card-ink);
  --transfer-them-divider-color:var(--ry-card-bd);
